eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   \"search\": () => (/* binding */ search)\n/* harmony export */ });\n/* harmony import */ var flexsearch__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! flexsearch */ \"flexsearch\");\n\nlet sectionIndex = new flexsearch__WEBPACK_IMPORTED_MODULE_0__.Document({\n    tokenize: \"full\",\n    document: {\n        id: \"url\",\n        index: \"content\",\n        store: [\n            \"title\",\n            \"pageTitle\"\n        ]\n    },\n    context: {\n        resolution: 9,\n        depth: 2,\n        bidirectional: true\n    }\n});\nlet data = [\n    {\n        \"url\": \"/\",\n        \"sections\": [\n            [\n                \"Welcome to TNTSearch!\",\n                null,\n                [\n                    \"Welcome to the official documentation of TNTSearch, a powerful and flexible full-text search engine written entirely in PHP. Whether you need simple keyword search or advanced features like boolean queries, fuzzy matching, geo search, and text classification, TNTSearch has you covered.\",\n                    \"Being crafted entirely in PHP, TNTSearch integrates natively into any PHP project without external service dependencies. It uses an inverted index stored in SQLite or Redis, and ranks results using the BM25 algorithm.\"\n                ]\n            ],\n            [\n                \"Quick start\",\n                \"quick-start\",\n                [\n                    \"Before you begin, make sure you have PHP and Composer installed on your system. Also make sure your server meets the following requirements:\",\n                    \"Installation\",\n                    \"TNTSearch is a Composer package:\",\n                    \"Creating an index\",\n                    \"Performing a search\",\n                    \"TNTSearch returns document IDs, not full records. To display results you need an additional query against your application database:\"\n                ]\n            ],\n            [\n                \"Getting help\",\n                \"getting-help\",\n                [\n                    \"For bugs, feature requests, or specific technical problems, please open an issue on the TNTSearch GitHub repository. Before opening a new issue:\",\n                    \"Stack Overflow\",\n                    \"For general questions or help with implementation, you can ask the community on Stack Overflow using the tag .\",\n                    \"Ask a Question on Stack Overflow\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/architecture-guide\",\n        \"sections\": [\n            [\n                \"Architecture guide\",\n                null,\n                [\n                    \"This guide explains the internal architecture of TNTSearch, how the major components fit together, and the design decisions behind the library.\"\n                ]\n            ],\n            [\n                \"High-level overview\",\n                \"high-level-overview\",\n                [\n                    \"TNTSearch is organized into these major subsystems:\"\n                ]\n            ],\n            [\n                \"Directory structure\",\n                \"directory-structure\",\n                []\n            ],\n            [\n                \"The inverted index\",\n                \"the-inverted-index\",\n                [\n                    \"At the core of TNTSearch is the inverted index, a data structure that maps terms to the documents containing them. Given a document like:\",\n                    '\"Romeo and Juliet is a tragedy\"',\n                    \"The inverted index stores entries like:\",\n                    'Notice that \"tragedy\" is stored as \"tragedi\" because the stemmer reduced it to its root form. Stopwords like \"and\", \"is\", \"a\" are typically filtered out.'\n                ]\n            ],\n            [\n                \"Engine contract\",\n                \"engine-contract\",\n                [\n                    \"Both storage engines (SQLite and Redis) implement the  interface, which defines methods for:\",\n                    \"The  contains shared logic used by both engines, including text stemming, document processing, and connector creation.\"\n                ]\n            ],\n            [\n                \"Search flow\",\n                \"search-flow\",\n                [\n                    \"When you call , here's what happens:\"\n                ]\n            ],\n            [\n                \"BM25 ranking\",\n                \"bm-25-ranking\",\n                [\n                    \"TNTSearch uses the BM25 algorithm for relevance ranking:\",\n                    \"Where:\",\n                    \"Documents matching more query terms and containing rarer terms score higher.\"\n                ]\n            ],\n            [\n                \"Boolean search flow\",\n                \"boolean-search-flow\",\n                [\n                    \"Boolean search uses a different approach:\"\n                ]\n            ],\n            [\n                \"Extending TNTSearch\",\n                \"extending-tnt-search\",\n                [\n                    \"Custom engines\",\n                    \"Implement the  interface to create a new storage backend:\",\n                    \"Custom tokenizers\",\n                    \"Extend  and implement . See the Custom tokenizers guide.\",\n                    \"Custom stemmers\",\n                    \"Create a class with a  method that returns the stemmed form of the word.\",\n                    \"Custom file readers\",\n                    \"Implement a reader class for non-text file formats and set it on the indexer with .\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/as-you-type-search\",\n        \"sections\": [\n            [\n                \"As-you-type search\",\n                null,\n                [\n                    \"As-you-type search (also known as prefix search or autocomplete search) returns results based on partial word matches. As the user types each character, TNTSearch matches the beginning of indexed terms, providing instant feedback.\"\n                ]\n            ],\n            [\n                \"Enabling as-you-type\",\n                \"enabling-as-you-type\",\n                []\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"When as-you-type is enabled, the last keyword in your search query is treated as a prefix. TNTSearch looks up all terms in the index that start with that prefix and returns matching documents.\",\n                    'For example, if a user types \"sha\", TNTSearch would match \"shakespeare\", \"shadow\", \"shall\", etc.'\n                ]\n            ],\n            [\n                \"Alternative API\",\n                \"alternative-api\",\n                [\n                    \"You can also use the setter method:\"\n                ]\n            ],\n            [\n                \"Usage with other features\",\n                \"usage-with-other-features\",\n                [\n                    \"As-you-type can be combined with fuzzy search for even more forgiving live search:\",\n                    \"For the best search-as-you-type experience, consider pairing this with a debounced input handler on the frontend to avoid excessive requests while the user is still typing.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/basic-search\",\n        \"sections\": [\n            [\n                \"Basic search\",\n                null,\n                [\n                    \"TNTSearch provides a straightforward API for creating indexes and performing full-text searches. This guide covers the core workflow: indexing your data, running searches, and working with results.\"\n                ]\n            ],\n            [\n                \"Creating an index\",\n                \"creating-an-index\",\n                [\n                    \"Before you can search, you need to create an index from your data source. An index is built by running a SQL query against your database and processing the results.\",\n                    \"The first column in your SELECT should be the primary key. All other columns will be indexed for full-text search.\",\n                    \"Custom primary key\",\n                    \"If your primary key is not named , specify it explicitly:\",\n                    \"Including the primary key in search\",\n                    \"By default, the primary key column is not indexed as searchable text. If you want to be able to search by ID values:\",\n                    \"Setting a language\",\n                    \"You can set a language to automatically configure the right stemmer:\",\n                    \"Supported languages: , , , , , , ,  (English), , , .\",\n                    \"Disabling output\",\n                    \"During indexing, TNTSearch prints progress to stdout. To suppress this:\"\n                ]\n            ],\n            [\n                \"Performing a search\",\n                \"performing-a-search\",\n                [\n                    \"Once an index exists, searching is simple:\",\n                    \"The second argument limits the number of results returned (default: 100).\",\n                    \"Understanding results\",\n                    \"The  method returns an array with the following structure:\",\n                    \"Results are ranked using the BM25 algorithm, which considers term frequency, inverse document frequency, and document length to produce relevance scores.\",\n                    \"TNTSearch returns document IDs, not full database records. You need to fetch the actual data from your database:\"\n                ]\n            ],\n            [\n                \"Multi-word queries\",\n                \"multi-word-queries\",\n                [\n                    \"When you search for multiple words, TNTSearch finds documents containing any of the words and ranks documents higher when they contain more of your search terms.\",\n                    \"For strict boolean logic (requiring all words or specific combinations), see the Boolean search guide.\"\n                ]\n            ],\n            [\n                \"Search with stemming\",\n                \"search-with-stemming\",\n                [\n                    'When a stemmer is configured, searches automatically account for word variations. For example, with the , a search for \"swimming\" will also match \"swim\", \"swimmer\", and \"swam\".',\n                    \"The stemmer is set during index creation and is automatically applied during search:\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/boolean-search\",\n        \"sections\": [\n            [\n                \"Boolean search\",\n                null,\n                [\n                    \"TNTSearch supports boolean search with , , and  operators, as well as grouping with parentheses. This gives your users fine-grained control over search queries.\"\n                ]\n            ],\n            [\n                \"Basic usage\",\n                \"basic-usage\",\n                [\n                    \"Use the  method instead of :\"\n                ]\n            ],\n            [\n                \"Operators\",\n                \"operators\",\n                [\n                    \"AND (implicit)\",\n                    \"Words separated by spaces are combined with AND. All words must appear in the document:\",\n                    \"OR\",\n                    \"Use  between words to match documents containing either term:\",\n                    \"NOT\",\n                    \"Use the tilde  prefix to exclude documents containing a term:\",\n                    \"Combining operators\",\n                    \"You can combine all operators in a single query:\"\n                ]\n            ],\n            [\n                \"Return format\",\n                \"return-format\",\n                [\n                    \"The  method returns the same format as regular search:\",\n                    \"Unlike the standard , boolean search does not compute BM25 relevance scores. Results are returned based on set operations (intersection, union, difference) rather than ranking.\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"Internally, TNTSearch converts your boolean query to postfix notation using the shunting-yard algorithm, then evaluates it as set operations:\",\n                    \"Stemming is applied to all search terms automatically, so boolean queries also benefit from word variation matching.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/custom-tokenizers\",\n        \"sections\": [\n            [\n                \"Custom tokenizers\",\n                null,\n                [\n                    \"Tokenizers control how text is split into individual terms for indexing and searching. TNTSearch ships with several built-in tokenizers and allows you to create custom ones for specialized use cases.\"\n                ]\n            ],\n            [\n                \"Default tokenizer\",\n                \"default-tokenizer\",\n                [\n                    \"The default  splits text on non-letter, non-number characters while preserving Unicode support:\",\n                    \"The default pattern is , which splits on anything that isn't a letter, number, connector punctuation, dash, or  symbol.\"\n                ]\n            ],\n            [\n                \"Built-in n-gram tokenizers\",\n                \"built-in-n-gram-tokenizers\",\n                [\n                    \"N-gram tokenizers break text into overlapping character sequences. They're useful for typo tolerance, substring matching, and languages without clear word boundaries.\",\n                    \"BigramTokenizer (2-gram)\",\n                    \"TrigramTokenizer (3-gram)\",\n                    \"FourgramTokenizer (4-gram)\",\n                    \"FivegramTokenizer (5-gram)\",\n                    \"NGramTokenizer (configurable)\",\n                    \"A general n-gram tokenizer with configurable min and max gram sizes:\",\n                    \"EdgeNgramTokenizer\",\n                    \"Generates n-grams from word edges, useful for prefix-based autocomplete:\",\n                    \"ProductTokenizer\",\n                    \"Creates a cartesian product of terms:\"\n                ]\n            ],\n            [\n                \"Setting a tokenizer\",\n                \"setting-a-tokenizer\",\n                [\n                    \"At configuration time\",\n                    \"At index creation time\",\n                    \"The tokenizer is stored in the index metadata and automatically loaded at search time.\"\n                ]\n            ],\n            [\n                \"Creating a custom tokenizer\",\n                \"creating-a-custom-tokenizer\",\n                [\n                    \"To create your own tokenizer, extend  and implement :\",\n                    \"Then use it when creating your index:\",\n                    \"Example: keeping hyphens in tokens\",\n                    'The default tokenizer treats hyphens as word separators. If you need to keep hyphenated terms together (e.g., product codes like \"70-200\"):',\n                    \"The tokenizer used at search time must match the tokenizer used at index time. TNTSearch stores the tokenizer class name in the index metadata and loads it automatically when you call .\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/filesystem-indexing\",\n        \"sections\": [\n            [\n                \"Filesystem indexing\",\n                null,\n                [\n                    \"TNTSearch can index text files directly from a directory on your filesystem, without needing a database. This is useful for searching through collections of documents, log files, markdown files, or any directory of text-based files.\"\n                ]\n            ],\n            [\n                \"Configuration\",\n                \"configuration\",\n                [\n                    \"Set the  to  and provide the directory path and file extension:\",\n                    \"Configuration options\"\n                ]\n            ],\n            [\n                \"Creating the index\",\n                \"creating-the-index\",\n                [\n                    \"The indexer automatically scans the directory and indexes all files matching the extension:\",\n                    \"No  call is needed since the data source is the filesystem, not a database.\"\n                ]\n            ],\n            [\n                \"Searching\",\n                \"searching\",\n                [\n                    \"Search works the same as with any other driver:\",\n                    \"Result format\",\n                    \"For filesystem indexes, the search results return file paths instead of document IDs:\",\n                    \"TNTSearch automatically maps internal document IDs back to file paths using the  table.\"\n                ]\n            ],\n            [\n                \"Use cases\",\n                \"use-cases\",\n                [\n                    \"Filesystem indexing is well-suited for:\",\n                    \"The filesystem driver uses the  to read file contents. It works with plain text files. For other formats (PDF, Word, etc.), you would need to extract the text first and write it as plain text files.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/fuzzy-search\",\n        \"sections\": [\n            [\n                \"Fuzzy search\",\n                null,\n                [\n                    \"Fuzzy search allows TNTSearch to find matching documents even when the search query contains typos or misspellings. It uses Levenshtein distance to find terms in the index that are similar to what the user typed.\"\n                ]\n            ],\n            [\n                \"Enabling fuzzy search\",\n                \"enabling-fuzzy-search\",\n                [\n                    \"Fuzzy search is disabled by default. Enable it before performing a search:\"\n                ]\n            ],\n            [\n                \"Configuration options\",\n                \"configuration-options\",\n                [\n                    \"You can fine-tune fuzzy search behavior with these settings:\",\n                    \"Fuzzy distance\",\n                    \"The maximum Levenshtein distance allowed between the search term and index terms. Default is .\",\n                    \"A distance of 1 allows single character insertions, deletions, or substitutions. A distance of 2 allows two such changes.\",\n                    \"Prefix length\",\n                    \"The minimum number of characters that must match exactly at the beginning of the word. Default is . This improves performance by reducing the number of candidates to check.\",\n                    \"Max expansions\",\n                    \"The maximum number of similar terms to consider. Default is . Higher values give more thorough results but take longer.\",\n                    \"No limit mode\",\n                    'By default, if a search term has an exact match, only the exact match is returned. Enable \"no limit\" mode to also include fuzzy matches alongside exact matches:'\n                ]\n            ],\n            [\n                \"Full example\",\n                \"full-example\",\n                []\n            ],\n            [\n                \"Reading current settings\",\n                \"reading-current-settings\",\n                [\n                    \"You can retrieve the current fuzzy search settings:\",\n                    \"Fuzzy search is more expensive than exact matching because it must compare the search term against many terms in the index. Use  and  to control the trade-off between recall and speed.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/geo-search\",\n        \"sections\": [\n            [\n                \"Geo search\",\n                null,\n                [\n                    \"TNTSearch includes a geographic search feature that lets you find locations within a given distance from a point. It uses the haversine formula to compute distances on the Earth's surface and stores precomputed trigonometric values for fast lookups.\"\n                ]\n            ],\n            [\n                \"Creating a geo index\",\n                \"creating-a-geo-index\",\n                [\n                    \"Geo indexes are separate from text indexes and use their own indexer and search classes. Your source data must include  and  columns.\",\n                    \"The query must select at least three columns: a primary key (), , and .\"\n                ]\n            ],\n            [\n                \"Searching for nearby locations\",\n                \"searching-for-nearby-locations\",\n                [\n                    \"Use  to find locations within a radius:\",\n                    \"Parameters\",\n                    \"Result format\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"The geo indexer precomputes and stores trigonometric values (, , , ) for each location during indexing. At search time, TNTSearch:\",\n                    \"The Earth radius used for calculations is 6,371 km.\"\n                ]\n            ],\n            [\n                \"Managing the geo index\",\n                \"managing-the-geo-index\",\n                [\n                    \"You can insert and delete locations dynamically:\",\n                    \"Geo search uses a separate index from text search. If you need both full-text search and geographic filtering, you'll need to maintain two indexes and combine results in your application logic.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/highlighting-snippets\",\n        \"sections\": [\n            [\n                \"Highlighting & snippets\",\n                null,\n                [\n                    \"TNTSearch includes built-in support for highlighting matched search terms in text and extracting relevant snippets from longer documents. These features help users quickly identify why a result matched their query.\"\n                ]\n            ],\n            [\n                \"Highlighting\",\n                \"highlighting\",\n                [\n                    \"The  method wraps matching terms in an HTML tag:\",\n                    \"Parameters\",\n                    \"Options\",\n                    \"Examples\"\n                ]\n            ],\n            [\n                \"Extracting snippets\",\n                \"extracting-snippets\",\n                [\n                    \"For long documents, you typically want to show a relevant portion of the text rather than the entire document. The  method extracts the most relevant passage containing the search terms:\",\n                    \"Parameters\",\n                    \"Example\",\n                    \"The snippet method finds the most relevant portion of the document where search terms appear closest together.\"\n                ]\n            ],\n            [\n                \"Combining highlighting and snippets\",\n                \"combining-highlighting-and-snippets\",\n                [\n                    \"For the best search results display, combine both features:\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/how-to-contribute\",\n        \"sections\": [\n            [\n                \"How to contribute\",\n                null,\n                [\n                    \"TNTSearch is an open-source project and contributions are welcome. Whether you're fixing a bug, adding a feature, improving documentation, or writing tests, this guide will help you get started.\"\n                ]\n            ],\n            [\n                \"Getting started\",\n                \"getting-started\",\n                []\n            ],\n            [\n                \"Making changes\",\n                \"making-changes\",\n                []\n            ],\n            [\n                \"Coding standards\",\n                \"coding-standards\",\n                []\n            ],\n            [\n                \"Reporting bugs\",\n                \"reporting-bugs\",\n                [\n                    \"When reporting a bug, include:\",\n                    \"Open issues at: github.com/teamtnt/tntsearch/issues\"\n                ]\n            ],\n            [\n                \"Feature requests\",\n                \"feature-requests\",\n                [\n                    \"Feature requests are welcome. Open an issue describing:\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/index-management\",\n        \"sections\": [\n            [\n                \"Index management\",\n                null,\n                [\n                    \"TNTSearch supports dynamic index updates, allowing you to insert new documents, update existing ones, and delete documents without rebuilding the entire index. This is essential for keeping your search index in sync with your application data.\"\n                ]\n            ],\n            [\n                \"Getting the index handle\",\n                \"getting-the-index-handle\",\n                [\n                    \"After selecting an index, get an indexer instance with :\"\n                ]\n            ],\n            [\n                \"Inserting documents\",\n                \"inserting-documents\",\n                [\n                    \"Add new documents to an existing index:\",\n                    \"The array keys must match the columns used when the index was created. After insertion, the document is immediately searchable:\"\n                ]\n            ],\n            [\n                \"Updating documents\",\n                \"updating-documents\",\n                [\n                    \"Update an existing document by providing its ID and the new content:\",\n                    \"The update process removes the old document data from the index and inserts the new data. Word counts and document frequencies are adjusted automatically.\",\n                    \"If the document ID doesn't exist in the index,  acts as an insert and the total document count increases.\"\n                ]\n            ],\n            [\n                \"Deleting documents\",\n                \"deleting-documents\",\n                [\n                    \"Remove a document from the index by its ID:\",\n                    \"After deletion, the document will no longer appear in search results. Word counts and document frequencies are decremented accordingly.\"\n                ]\n            ],\n            [\n                \"Monitoring index state\",\n                \"monitoring-index-state\",\n                [\n                    \"You can check the total number of indexed documents:\",\n                    \"This count updates automatically as you insert and delete documents.\"\n                ]\n            ],\n            [\n                \"Full example\",\n                \"full-example\",\n                []\n            ],\n            [\n                \"Rebuilding from scratch\",\n                \"rebuilding-from-scratch\",\n                [\n                    \"If your data has changed significantly, it may be more efficient to rebuild the index entirely rather than performing many individual updates:\",\n                    \"Creating an index with the same name replaces the existing one.\",\n                    \"For applications with frequent data changes, consider running index updates in a queue or background job to avoid slowing down your main application flow.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/installation\",\n        \"sections\": [\n            [\n                \"Installation\",\n                null,\n                [\n                    \"TNTSearch is distributed as a Composer package and can be installed in any PHP project.\"\n                ]\n            ],\n            [\n                \"Requirements\",\n                \"requirements\",\n                [\n                    \"Make sure your server meets the following requirements:\",\n                    \"If you plan to use the Redis storage engine, you also need the  package (installed automatically as a dependency).\"\n                ]\n            ],\n            [\n                \"Install via Composer\",\n                \"install-via-composer\",\n                [\n                    \"This will install TNTSearch and all required dependencies.\"\n                ]\n            ],\n            [\n                \"Configuration\",\n                \"configuration\",\n                [\n                    \"TNTSearch requires a configuration array to connect to your data source and define where indexes are stored. Here is a complete example:\",\n                    \"Configuration options\",\n                    \"Supported database drivers\",\n                    \"TNTSearch can index data from any of these databases:\",\n                    \"The  setting determines where your source data lives. The index itself is always stored in SQLite (default) or Redis, regardless of the source database driver.\"\n                ]\n            ],\n            [\n                \"Verify installation\",\n                \"verify-installation\",\n                [\n                    \"To verify everything is working, create a simple test script:\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/keyword-extraction\",\n        \"sections\": [\n            [\n                \"Keyword extraction\",\n                null,\n                [\n                    \"TNTSearch includes a keyword extraction feature based on the RAKE (Rapid Automatic Keyword Extraction) algorithm. RAKE identifies key phrases in text by analyzing word frequency and co-occurrence, without requiring any training data.\"\n                ]\n            ],\n            [\n                \"Basic usage\",\n                \"basic-usage\",\n                [\n                    \"RAKE automatically filters out stopwords and scores phrases based on word degree and frequency.\"\n                ]\n            ],\n            [\n                \"Extracting from longer text\",\n                \"extracting-from-longer-text\",\n                [\n                    \"RAKE works particularly well with longer, more technical text:\",\n                    \"The returned array is sorted by score (highest first), with the top third of phrases returned.\"\n                ]\n            ],\n            [\n                \"Without scores\",\n                \"without-scores\",\n                [\n                    \"To get just the keyword phrases without scores:\"\n                ]\n            ],\n            [\n                \"Language support\",\n                \"language-support\",\n                [\n                    \"RAKE uses stopword lists to identify phrase boundaries. By default, it uses English stopwords. You can specify a different language:\"\n                ]\n            ],\n            [\n                \"How RAKE works\",\n                \"how-rake-works\",\n                []\n            ],\n            [\n                \"Helper methods\",\n                \"helper-methods\",\n                [\n                    \"The Rake class exposes lower-level methods for custom analysis:\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/redis-engine\",\n        \"sections\": [\n            [\n                \"Redis engine\",\n                null,\n                [\n                    \"TNTSearch supports Redis as an alternative storage engine to SQLite. The Redis engine stores the inverted index in Redis data structures, making it suitable for high-throughput applications and distributed environments where multiple servers need access to the same index.\",\n                    \"For a hands-on, end-to-end walkthrough — from an empty database to an index shared across several servers — see the Redis-backed search tutorial. This page is the configuration reference.\"\n                ]\n            ],\n            [\n                \"Requirements\",\n                \"requirements\",\n                [\n                    \"The Redis engine requires the  package, which is included as a dependency of TNTSearch:\",\n                    \"You also need a running Redis server.\"\n                ]\n            ],\n            [\n                \"Configuration\",\n                \"configuration\",\n                [\n                    \"To use Redis, set the  to  and provide Redis connection details:\",\n                    \"Full configuration options\",\n                    \"Secure connection example\"\n                ]\n            ],\n            [\n                \"Creating and searching an index\",\n                \"creating-and-searching-an-index\",\n                [\n                    \"The API is identical to the SQLite engine. You create and search indexes the same way:\",\n                    \"All search features work with Redis: boolean search, fuzzy search, as-you-type, and stemming.\"\n                ]\n            ],\n            [\n                \"Redis data structures\",\n                \"redis-data-structures\",\n                [\n                    \"TNTSearch stores the index using these Redis key patterns:\"\n                ]\n            ],\n            [\n                \"Flushing an index\",\n                \"flushing-an-index\",\n                [\n                    \"To completely remove an index from Redis:\",\n                    \"The Redis engine's  method scans and deletes all keys matching the index name prefix.\"\n                ]\n            ],\n            [\n                \"When to use Redis\",\n                \"when-to-use-redis\",\n                [\n                    \"The Redis engine is ideal when:\",\n                    \"Redis stores everything in memory. Large indexes will consume significant RAM. Monitor your Redis memory usage and consider using SQLite for very large datasets that don't fit comfortably in memory.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/redis-tutorial\",\n        \"sections\": [\n            [\n                \"Redis-backed search\",\n                null,\n                [\n                    \"This tutorial walks through building a working full-text search index end to end, using Redis as the storage engine. By the end you will have indexed a real table, run searches against it, peeked at the raw keys Redis stores, and shared a single index across several application servers.\",\n                    \"If you just need the configuration reference — the full list of  options and key patterns — see the Redis engine page. This guide is the practical companion to it.\"\n                ]\n            ],\n            [\n                \"What you'll build\",\n                \"what-you-ll-build\",\n                [\n                    \"Imagine a blog running behind a load balancer with three PHP application servers. Every server needs to search the same set of articles. With the default SQLite engine each server would carry its own index file, and you'd have to copy that file around after every re-index. With Redis, all three servers point at one shared, in-memory index instead.\",\n                    \"We'll get there in five steps:\"\n                ]\n            ],\n            [\n                \"Prerequisites\",\n                \"prerequisites\",\n                [\n                    \"You'll need:\",\n                    \"The fastest way to get a Redis server for local development is Docker:\",\n                    \"That gives you Redis listening on . Any other Redis install works just as well.\"\n                ]\n            ],\n            [\n                \"Step 1 — Install the packages\",\n                \"step-1-install-the-packages\",\n                [\n                    \"TNTSearch ships with  as a dependency, so a single Composer command pulls in everything the Redis engine needs:\",\n                    \"The Redis engine talks to Redis through the pure-PHP Predis client — you do not need the  C extension installed. If Predis is missing for any reason, install it explicitly with .\"\n                ]\n            ],\n            [\n                \"Step 2 — Prepare some data to index\",\n                \"step-2-prepare-some-data-to-index\",\n                [\n                    \"So the tutorial is reproducible, create a small  table and drop a few rows in. The source data can live in any supported driver — here we use MySQL:\",\n                    \"The first column in your query is always treated as the primary key, and every other column is indexed as searchable text.\"\n                ]\n            ],\n            [\n                \"Step 3 — Configure the Redis engine\",\n                \"step-3-configure-the-redis-engine\",\n                [\n                    \"The only thing that changes compared to a normal SQLite setup is the  class plus a few  connection keys. Everything else — , ,  — still describes where your source data lives, not where the index goes.\",\n                    \"is optional with the Redis engine — there is no index file on disk. It's only used when the  driver needs a place to store its path map. You can leave it out for database-backed indexes.\"\n                ]\n            ],\n            [\n                \"Step 4 — Build the index\",\n                \"step-4-build-the-index\",\n                [\n                    \"Building the index is identical to every other engine. You give the index a name, hand it a SQL query, and call :\",\n                    \"That's it. Instead of writing an  SQLite file, TNTSearch has now populated a set of Redis keys, all namespaced under .\",\n                    \"Calling  with a name that already exists flushes the old index first. The Redis engine scans for every key matching the index prefix and deletes it, so re-indexing never leaves stale terms behind.\"\n                ]\n            ],\n            [\n                \"Step 5 — Look at what Redis stored\",\n                \"step-5-look-at-what-redis-stored\",\n                [\n                    \"This is the fun part. Open  and list the keys for the index:\",\n                    \"You'll see keys following a predictable pattern:\",\n                    \"Each term becomes a  hash (how many documents contain it, how many total hits), and each term-in-a-document becomes a  hash. To inspect a single term:\",\n                    \"The full list of key patterns and their fields is documented on the Redis engine reference page.\"\n                ]\n            ],\n            [\n                \"Step 6 — Search it\",\n                \"step-6-search-it\",\n                [\n                    \"Searching works exactly the same as with any engine — the storage backend is completely transparent to the search API:\",\n                    \"returns document IDs ranked by relevance, not full rows:\",\n                    \"Every search feature you'd use with SQLite works with Redis too:\",\n                    \"See Basic search, Boolean search, and Fuzzy search for the details of each.\",\n                    \"Turning IDs into records\",\n                    \"TNTSearch returns IDs so it stays database-agnostic. Fetch the actual articles yourself, preserving the relevance order:\"\n                ]\n            ],\n            [\n                \"Step 7 — Share the index across servers\",\n                \"step-7-share-the-index-across-servers\",\n                [\n                    \"Here's the payoff. Because the index lives in Redis rather than in a local file, any server that can reach the same Redis instance sees the same index instantly.\",\n                    \"A typical setup splits the work:\",\n                    \"One indexer (a cron job, a queue worker, or an admin box) builds and updates the index:\",\n                    \"Every web server just searches, pointing at the same :\",\n                    \"Add a fourth web server tomorrow and it needs zero index setup — it reads the shared keys the moment it connects. No file copying, no per-deploy sync, no stale replicas.\",\n                    \"You can also keep the index fresh incrementally without a full rebuild. When a single article changes, update just that document:\"\n                ]\n            ],\n            [\n                \"Connecting to a remote or managed Redis\",\n                \"connecting-to-a-remote-or-managed-redis\",\n                [\n                    \"For production you'll usually point at a managed Redis (Elasticache, Redis Cloud, Upstash, …) over TLS with a password. The Redis engine supports that directly:\",\n                    \"The complete list of connection options is on the Redis engine reference page.\"\n                ]\n            ],\n            [\n                \"Should you use Redis?\",\n                \"should-you-use-redis\",\n                [\n                    \"Reach for the Redis engine when:\",\n                    \"Stay on the default SQLite engine when you're running a single server, your index is large, or you want a zero-dependency, on-disk setup.\",\n                    \"Redis keeps the entire index in RAM. A large corpus can consume significant memory, so monitor your Redis memory usage and enable persistence (RDB or AOF) if you want the index to survive a Redis restart without a rebuild. For very large datasets that don't fit comfortably in memory, SQLite is often the better fit.\"\n                ]\n            ],\n            [\n                \"Next steps\",\n                \"next-steps\",\n                []\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/sqlite-engine\",\n        \"sections\": [\n            [\n                \"SQLite engine\",\n                null,\n                [\n                    \"The SQLite engine is the default storage backend for TNTSearch. It stores the inverted index in a local SQLite database file, making it a zero-configuration option that works out of the box without any external dependencies.\"\n                ]\n            ],\n            [\n                \"Configuration\",\n                \"configuration\",\n                [\n                    \"SQLite is the default engine. You don't need to specify it explicitly:\",\n                    \"To be explicit, you can set the engine:\",\n                    \"The index file will be created in the  directory with the name you specify when calling .\"\n                ]\n            ],\n            [\n                \"Write-Ahead Logging (WAL)\",\n                \"write-ahead-logging-wal\",\n                [\n                    \"For better concurrent read/write performance, you can enable SQLite's WAL mode:\",\n                    \"WAL mode allows readers and writers to operate concurrently without blocking each other, which is beneficial when you need to update the index while searches are being performed.\"\n                ]\n            ],\n            [\n                \"Index schema\",\n                \"index-schema\",\n                [\n                    \"The SQLite engine creates the following tables:\"\n                ]\n            ],\n            [\n                \"When to use SQLite\",\n                \"when-to-use-sq-lite\",\n                [\n                    \"The SQLite engine is ideal when:\",\n                    \"For high-throughput scenarios or when you need shared index access across multiple servers, consider the Redis engine.\"\n                ]\n            ],\n            [\n                \"File management\",\n                \"file-management\",\n                [\n                    \"Each index is stored as a single SQLite file. You can:\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/stemming\",\n        \"sections\": [\n            [\n                \"Stemming\",\n                null,\n                [\n                    'When you search for \"swimming\" in a document, wouldn\\'t it be great if your search tool could understand that \"swim\", \"swimmer\", and \"swam\" are all related to your search term? That\\'s the magic of stemming.',\n                    \"Stemming is a method where search engines identify the base or root form of words. It helps the search engine to consider various word forms when you make a search. This ensures you get broader and more relevant results. Here's why stemming is an essential tool in search:\",\n                    'Broadened Searches: Through stemming, a search for \"swimming\" could pull up results with \"swimmer\" or \"swam\". This expands the range of your search without the need to input every word variation.',\n                    \"Conserving Space: Instead of keeping every variation of a word, search engines can focus on the root. This results in faster, more efficient searches.\",\n                    'Uniformity: Stemming creates a level field. Whether an article mentions \"jogging\" or \"jogger\", a search for \"jog\" will capture both.',\n                    \"Enhanced Accuracy: Recognizing word variants allows stemming to refine search results for better relevance.\",\n                    'Now, stemming is like a librarian understanding that books on \"cooking\", \"cooked\", and \"cookery\" all revolve around the same theme. It makes search engines more intuitive and user-centric.',\n                    \"TNTSearch isn't just any tool; it's a robust one. It supports a diverse set of stemmers:\",\n                    'One of the interesting stemmers on the list is the PorterStemmer. Developed by Martin Porter in the early \\'80s, the Porter Stemmer is one of the most well-known stemming algorithms. It works by chopping off word endings to identify the base form of a word. For instance, the word \"fishing\" would be stemmed to \"fish\". The Porter algorithm is especially noted for its simplicity and efficiency in the English language.',\n                    \"By integrating these stemmers, TNTSearch ensures its users have a comprehensive, adaptable, and globally-minded tool at their fingertips.\",\n                    \"Hope this offers clarity on stemming and how TNTSearch implements it!\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/text-classification\",\n        \"sections\": [\n            [\n                \"Text classification\",\n                null,\n                [\n                    \"TNTSearch includes a Naive Bayes text classifier that can learn to categorize documents based on training data. This is useful for spam detection, sentiment analysis, topic categorization, and other text classification tasks.\"\n                ]\n            ],\n            [\n                \"Basic usage\",\n                \"basic-usage\",\n                [\n                    \"The classifier has a simple learn-and-predict API:\"\n                ]\n            ],\n            [\n                \"Training the classifier\",\n                \"training-the-classifier\",\n                [\n                    \"Use the  method to train the classifier with labeled examples. The more examples you provide, the more accurate predictions will be:\",\n                    \"Training from a dataset\",\n                    \"For real-world applications, you'll typically train from a dataset:\"\n                ]\n            ],\n            [\n                \"Saving and loading\",\n                \"saving-and-loading\",\n                [\n                    \"You can persist a trained classifier to disk and load it later:\"\n                ]\n            ],\n            [\n                \"How it works\",\n                \"how-it-works\",\n                [\n                    \"The classifier uses the Naive Bayes algorithm with Laplace smoothing:\",\n                    \"Laplace smoothing (add-one smoothing) ensures that unseen words don't zero out the probability calculation.\"\n                ]\n            ],\n            [\n                \"Use cases\",\n                \"use-cases\",\n                [\n                    \"The classifier uses the same tokenizer and stemmer as the search engine. For best results, ensure your training data is representative of the text you'll be classifying in production.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/tokenization\",\n        \"sections\": [\n            [\n                \"Diving into Tokenization\",\n                null,\n                [\n                    \"Imagine you're handed a jigsaw puzzle, and instead of the picture being already cut into individual pieces, it's still one complete image. You would first need to break it down into pieces before you could start solving the puzzle. This concept mirrors tokenization in the realm of search engines.\",\n                    \"Tokenization is the process of breaking down text into individual words, terms, or symbols, often referred to as . Think of it as dissecting a sentence into its individual words. By doing this, search engines can analyze, categorize, and process the content more efficiently. Here's why tokenization is a cornerstone in the search world:\",\n                    \"Precision: By examining content token-by-token, search engines can pinpoint exact matches and closely related content with higher accuracy.\",\n                    \"Speed: Searching through tokens (individual words or symbols) is faster than processing entire strings or blocks of text repeatedly.\",\n                    \"Versatility: Tokenization paves the way for other essential processes like stemming and indexing, further refining the search experience.\",\n                    \"Language Adaptability: Since languages have different rules and structures, tokenization helps adapt the search engine to diverse linguistic nuances, ensuring relevance across multiple languages.\",\n                    \"In a way, tokenization is akin to a chef meticulously preparing ingredients before cooking. Each ingredient (or token) plays a crucial role in the final dish (or search result).\",\n                    \"TNTSearch employs advanced tokenization techniques to ensure that when you input a query, it dissects and understands your input at a granular level, leading to more relevant and accurate search results.\",\n                    \"Tokenization is one of the foundational processes that ensure search engines like TNTSearch are efficient, accurate, and versatile in handling queries across various languages and content types.\"\n                ]\n            ]\n        ]\n    },\n    {\n        \"url\": \"/docs/understanding-indexing\",\n        \"sections\": [\n            [\n                \"Understanding Indexing\",\n                null,\n                [\n                    \"Think of a thick book you're trying to navigate. If you're looking for mentions of a topic like quantum mechanics, but the book doesn't have an index, you'd need to flip through every page — and that's not fun or fast. However, if there's a handy index at the back, you can quickly jump to every spot where quantum mechanics shows up. That's the magic of an index. It tells you where things are without making you search everywhere.\",\n                    \"Search engines use a similar idea to look through all the information they have. Here's why they use an index:\",\n                    \"Speed: With an index, a search engine can jump right to the data it needs. Without one, it's like reading a book from cover to cover for every single question you have.\",\n                    \"Relevance & Ranking: An index doesn't just tell a search engine where words are; it can also say which ones show up a lot or in important places. This helps the search engine decide which results are the most useful.\",\n                    \"Complex Queries: If you're trying to make a fancy or specific search, an index helps the search engine understand and find what you're looking for without getting overwhelmed.\",\n                    \"Saving Space: While indexes do take up some room, they're like a condensed version of the main content. It's often more space-saving to look through an index than to rummage through all the raw info over and over.\",\n                    \"So, before a search engine can quickly answer questions, it has to create an index of its info. This is a bit like making a roadmap that says where everything is.\",\n                    \"Now, there's a special kind of index called an \\\"inverted index\\\". And that's where TNTSearch shines. By default, TNTSearch uses an SQLite database to keep this index. But it's also flexible. If you prefer, you can switch to storing your index in a Redis database. Here's a quick example of how you can set that up:\"\n                ]\n            ]\n        ]\n    }\n];\nfor (let { url , sections  } of data){\n    for (let [title, hash, content] of sections){\n        sectionIndex.add({\n            url: url + (hash ? \"#\" + hash : \"\"),\n            title,\n            content: [\n                title,\n                ...content\n            ].join(\"\\n\"),\n            pageTitle: hash ? sections[0][0] : undefined\n        });\n    }\n}\nfunction search(query, options = {}) {\n    let result = sectionIndex.search(query, {\n        ...options,\n        enrich: true\n    });\n    if (result.length === 0) {\n        return [];\n    }\n    return result[0].result.map((item)=>({\n            url: item.id,\n            title: item.doc.title,\n            pageTitle: item.doc.pageTitle\n        }));\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///./src/markdoc/search.mjs\n");

